			[TestMethod]
			public void Beq_SourceIs2InProtectedBlock_TargetIs3InSameProtectedBlock_Passes() {
				var body = GetSourceTestMethod();
				AddTargetAndSource(body, OpCodes.Beq, 2, ExceptionHandlerType.Finally, 3, ExceptionHandlerType.Finally);
				var result = ILValidator_Privates.VerifyBranches(body);
				Assert.IsTrue(result.IsValid, string.Join(Environment.NewLine, result.ErrorMessages));
			}
			[TestMethod]
			public void Beq_SourceIs2InProtectedBlock_TargetIs4InSameProtectedBlock_Passes() {
				var body = GetSourceTestMethod();
				AddTargetAndSource(body, OpCodes.Beq, 2, ExceptionHandlerType.Finally, 4, ExceptionHandlerType.Finally);
				var result = ILValidator_Privates.VerifyBranches(body);
				Assert.IsTrue(result.IsValid, string.Join(Environment.NewLine, result.ErrorMessages));
			}
			[TestMethod]
			public void Beq_SourceIs2InProtectedBlock_TargetIs5InSameFilter_Fails() {
				var body = GetSourceTestMethod();
				AddTargetAndSource(body, OpCodes.Beq, 2, ExceptionHandlerType.Finally, 5, ExceptionHandlerType.Filter);
				var result = ILValidator_Privates.VerifyBranches(body);
				Assert.IsFalse(result.IsValid);
				StringAssert.EndsWith(result.ErrorMessages[0], "contains branch instruction [0002], but not its target(s)!");
			}
